public void init()
{
    InventDimCtrl_Frm_OnhandItem inventDimCtrl = InventDimCtrl_Frm_OnhandItem::newFromForm(formRun);

    InventDimParm dimParmVisibleGrid = InventDimParm::construct();

    // Enable dimensions
    dimParmVisibleGrid.InventSiteIdFlag(true);
    dimParmVisibleGrid.InventLocationIdFlag(true);
    dimParmVisibleGrid.InventBatchIdFlag(true);
    dimParmVisibleGrid.wMSLocationIdFlag(true);
    dimParmVisibleGrid.SerialIdFlag(true);

    // Assign to controller
    inventDimCtrl.parmDimParmVisibleGrid(dimParmVisibleGrid);

    // Call init AFTER setting the parm
    inventDimCtrl.init();

}
